from core import *

@register('limits','quadratic-Weyl-distance-moment','polynomial-Weyl-differencing','van-der-Corput-differencing-and-torus-integration','Two deterministic fractional-part coordinates must be shown jointly uniform despite their arithmetic dependence. Differencing quadratic phases reduces every nontrivial Fourier character to a controlled geometric sum.','The earlier irrational-rotation family concerns a linear orbit and a fixed phase correlation. Here the second coordinate is quadratic and the essential new step is differencing, not assuming independence.',[{'caseId':'distance-moment-'+str(p),'p':p,'purpose':'Distinct absolute-distance moments; the irrational orbit itself is fixed to avoid fake parameter novelty.'} for p in range(1,17)],['fractional parts','geometric exponential sums','van der Corput inequality','Weyl criterion','Riemann-integrable torus averages'])
def quadratic_weyl(case):
 p=case['p'];A=R(2,(p+1)*(p+2));u,v,h=s.symbols('u v h',real=True);a,b=s.symbols('a b',integer=True);N=s.symbols('N',integer=True)
 phi=s.sqrt(2)*(a*N+b*N*N);difference=s.expand(phi.subs(N,N+h)-phi)
 ck('Quadratic phase differencing leaves a linear irrational coefficient',difference,2*s.sqrt(2)*b*h*N+s.sqrt(2)*(a*h+b*h*h))
 ck('Independent triangle integration gives the limiting moment',2*s.integrate(s.integrate((u-v)**p,(v,0,u)),(u,0,1)),A)
 analytic('Joint polynomial equidistribution',['The fixed irrational coefficient is square root two. Fourier character indices are integers, not both zero. The distance power is a positive integer.'],['For a nonzero character(a,b), the exponential phase is square-root-two times(a*n+b*n squared). If b=0, the average is a geometric sum with ratio different from one and tends to zero.','If b is nonzero, every fixed positive-lag correlation has a linear phase with nonzero irrational slope2*b*h*sqrt2, so it also tends to zero by the same geometric-sum estimate.','The van der Corput inequality, with a fixed correlation window H and then the sample size tending to infinity, bounds the squared limsup of the original average by1/H. Let H tend to infinity.','Weyl criterion therefore gives joint uniformity on the square. The fractional-coordinate distance power is bounded and has discontinuities only on the boundary identifications, a null set, so Riemann-integrable equidistribution applies.','Split the square along the diagonal and integrate twice the lower triangle to obtain the exact moment.'])
 return candidate(r'\{x\}=x-\lfloor x\rfloor.'+T('Evaluate ')+r'\lim_{N\to\infty}\frac1N\sum_{n=1}^N\left|\{n\sqrt2\}-\{n^2\sqrt2\}\right|^{'+str(p)+r'}.',A,[(R(1,(p+1)**2),'Multiply the coordinate moments instead of integrating their distance'),(R(1,p+1),'Treat the distance as uniform on the unit interval'),(R(1,p+2),'Integrate only the distance power and lose its triangular density normalization'),(R(2,(p+2)*(p+3)),'Increase the distance power by one in both integrations'),(R(2,p*(p+1)),'Decrease the distance power by one in both integrations'),(A/2,'Integrate only one of the two triangles')],[T('Test joint equidistribution with an arbitrary nonzero integer Fourier character.'),r'z_n=e^{2\pi i\sqrt2(an+bn^2)},\qquad(a,b)\in\mathbb Z^2\setminus\{(0,0)\}',T('When the quadratic coefficient vanishes this is a geometric sum with nonunit ratio. Otherwise every fixed-lag correlation has the linear phase below.'),r'z_{n+h}\overline{z_n}=e^{2\pi i\sqrt2(2bhn+ah+bh^2)}',T('Its mean tends to zero because its slope is irrational. Van der Corput gives squared limsup at most one over an arbitrary window length; letting that length grow proves every nontrivial character has zero mean.'),T('Weyl criterion now applies jointly; arithmetic dependence has been checked rather than treated as independence.'),r'\lim=\int_0^1\int_0^1|u-v|^{'+str(p)+r'}\,\mathrm dv\,\mathrm du=2\int_0^1\int_0^u(u-v)^{'+str(p)+r'}\,\mathrm dv\,\mathrm du='+L(A)],'quadratic-irrational-orbit-joint-distance-moment')

@register('limits','AGM-invariant-limit','elliptic-agm-invariance','two-to-one-integral-substitution-and-monotone-iteration','The arithmetic-geometric iteration has no elementary closed form. An integral invariant must be proved by a global substitution, and convergence then identifies its common limit with an elliptic integral.','Shared global idea with integration AGM invariance; the exact initial elliptic parameter is recorded for cross-topic task aliasing.',[{'caseId':'elliptic-parameter-'+str(p),'p':str(p),'normalizedTaskKey':'AGM-invariant-parameter:'+str(p),'purpose':'Different elliptic shape parameters; the initial arithmetic coordinate is normalized to one.'} for p in [R(1,3),R(2,5),R(3,7),R(4,9),R(5,11),R(1,5),R(2,7),R(3,8),R(5,8),R(7,9),R(8,11),R(9,13),R(3,10),R(7,10),R(4,13),R(10,13)]],['positive improper integrals','monotone sequences','change of variables','dominated convergence'])
def agm(case):
 p=R(case['p']);b=s.sqrt(1-p);A=pi/(2*s.elliptic_k(p));v=s.symbols('v',positive=True);aa,bb=s.symbols('a b',positive=True);u=(v-aa*bb/v)/2;mean=(aa+bb)/2;geom=s.sqrt(aa*bb)
 ck('Substitution factors the first radicand exactly',(v*v+aa*aa)*(v*v+bb*bb)/(4*v*v),u*u+mean*mean)
 ck('The second radicand is a positive square',u*u+geom*geom,(v+aa*bb/v)**2/4)
 ck('Jacobian yields the exact half-line-to-whole-line factor',s.diff(u,v),(v*v+aa*bb)/(2*v*v))
 condition('Finite elliptic parameter domain',0<p<1,'The initial coordinates are positive; the integral K is finite and strictly positive in the stated parameter convention.')
 analytic('AGM invariant and common limit',['All iterates are positive. The elliptic integral uses parameter p, not modulus squared silently substituted afterward.'],['For positive a,b, define I(a,b)=integral0infinity[(t squared+a squared)(t squared+b squared)]^(-1/2)dt. Use u=(t-ab/t)/2, a strictly increasing bijection from the positive half-line onto the real line.','The two checked square identities and Jacobian transform I(a,b) into one half the same integrand over the whole real line with new parameters(a+b)/2 and sqrt(ab). Evenness proves exact invariance.','After ordering the initial coordinates, arithmetic means decrease and geometric means increase; their difference at the next step is at most half the current difference. They converge to a common positive L.','Dominated convergence, using the fixed positive lower initial coordinate, gives I(L,L)=pi/(2L). The substitution t=b*tan theta shows I(1,b)=K(1-b squared), in the stated parameter convention.'])
 return candidate(r'a_0=1,\quad b_0='+L(b)+r',\qquad a_{n+1}=\frac{a_n+b_n}{2},\quad b_{n+1}=\sqrt{a_nb_n}.'+T('With the parameter convention ')+r'K(p)=\int_0^{\pi/2}\frac{\mathrm d\theta}{\sqrt{1-p\sin^2\theta}}\quad(0<p<1),'+T('find ')+r'\lim_{n\to\infty}a_n.',A,[(2*A,'Lose the half factor in the positive-half-line to whole-line transformation'),(A/2,'Apply the evenness half factor twice'),(b*A,'Omit the initial-variable normalization in the tangent substitution'),(A/b,'Invert the initial-variable normalization in the tangent substitution'),((1-p)*A,'Use the squared geometric coordinate as the scale factor'),(A/(1-p),'Invert the squared initial geometric coordinate')],[r'I(a,b)=\int_0^\infty\frac{\mathrm dt}{\sqrt{(t^2+a^2)(t^2+b^2)}},\qquad u=\frac12\left(t-\frac{ab}{t}\right)',r'u^2+\left(\frac{a+b}2\right)^2=\frac{(t^2+a^2)(t^2+b^2)}{4t^2},\qquad u^2+ab=\frac{(t+ab/t)^2}{4}',T('The substitution is increasing onto the whole real line. Its Jacobian gives one half of an even integral, proving the exact invariant.'),r'I(a,b)=I\!\left(\frac{a+b}2,\sqrt{ab}\right)',T('The arithmetic coordinate decreases, the geometric coordinate increases, and their difference contracts. Thus both tend to a common positive limit; the fixed positive lower bound permits dominated convergence in the integral.'),r'I(1,'+L(b)+r')=I(L,L)=\frac\pi{2L}',r't='+L(b)+r'\tan\theta\quad\Longrightarrow\quad I(1,'+L(b)+r')=K('+L(p)+r')'],'positive-AGM-iteration-elliptic-parameter-invariant')

@register('limits','Lambert-product-singularity','dense-product-Mellin-singularity','positive-double-series-and-uniform-scaled-sum-bound','The product logarithm has infinitely many scales. Expanding each logarithm gives a positive double series; a uniform bound across the second index is required before interchanging its singular limit.','The geometric-cutoff product has only logarithmically many active factors. This arithmetic-lattice product has an order-one-over-t active range and a Gamma-zeta constant.',[{'caseId':'weight-exponent-'+str(p),'p':str(p),'purpose':'Different arithmetic-lattice weight exponents change the singular power and Mellin moment; no time-scale copies.'} for p in [R(j,2) for j in range(1,17)]],['infinite products','Tonelli theorem','Gamma integral','Riemann sums with tail bounds','dominated series'])
def lambert(case):
 p=R(case['p']);A=-s.gamma(p+1)*s.zeta(p+2);v=s.symbols('v',positive=True)
 for j in [1,2,3]:ck('Independent exact Laplace moment at logarithm index '+str(j),s.integrate(v**p*s.exp(-j*v),(v,0,s.oo)),s.gamma(p+1)/s.Integer(j)**(p+1))
 ck('Change-of-scale coefficient in each fixed-index integral',s.integrate(v**p*s.exp(-v),(v,0,s.oo)),s.gamma(p+1))
 condition('Summable dominating zeta exponent',p>0 and p+2>1,'The finite actual exponents are positive, so both Gamma integrability and the eventual zeta sum converge.')
 analytic('Uniform double-series singular limit',['The product is defined by its convergent real logarithmic sum for every positive t; each base factor is in(0,1).','The power p is the stated positive rational number.'],['Expand minus ln(1-exp(-kt)) as sum over j of exp(-jkt)/j. All terms are nonnegative, so Tonelli permits the double sum before any limiting step.','For each fixed j, t^(p+1)sum k^p exp(-jkt) is a Riemann sum tending to Gamma(p+1)/j^(p+1). The infinite tail is controlled by exponential decay.','Uniformly for v>0, v^(p+1)sum k^p exp(-vk) is bounded by a finite constant depending only on p. For v<=1 compare with the integral of(x+1)^p exp(-vx). For v>=1 use exp(-vk)<=exp(-v/2)exp(-k/2), whose polynomially weighted series converges.','With v=jt, the outer summand after normalization is bounded by C_p/j^(p+2). Dominated convergence for the j series therefore gives Gamma(p+1)zeta(p+2), with a negative sign for the product logarithm.'])
 return candidate(r'P(t)=\prod_{k=1}^\infty(1-e^{-kt})^{k^{'+L(p)+r'}}\quad(t>0).'+T('Real powers are defined using the natural logarithm. Use ')+r'\Gamma(a)=\int_0^\infty u^{a-1}e^{-u}\,\mathrm du\ (a>0),\qquad\zeta(s)=\sum_{j=1}^\infty j^{-s}\ (s>1).'+T('Find ')+r'\lim_{t\downarrow0}t^{'+L(p+1)+r'}\ln P(t).',A,[(-s.gamma(p+1)*s.zeta(p+1),'Omit the logarithmic expansion factor one over j'),(-s.gamma(p+1)*s.zeta(p+3),'Insert the logarithmic expansion factor twice'),(-s.gamma(p+2)*s.zeta(p+2),'Increase the Laplace moment exponent by one'),(-s.gamma(p)*s.zeta(p+2),'Use the preceding Gamma moment'),(-s.gamma(p+1)*s.zeta(p+4),'Apply the logarithmic expansion divisor three times'),(-s.gamma(p+1),'Retain only the first logarithmic expansion term')],[r'-\ln P(t)=\sum_{j=1}^\infty\frac1j\sum_{k=1}^\infty k^{'+L(p)+r'}e^{-jkt}',T('All terms are nonnegative, so the double sum is justified by Tonelli. For each fixed outer index, use a scaled Riemann sum.'),r't^{'+L(p+1)+r'}\sum_{k=1}^\infty k^{'+L(p)+r'}e^{-jkt}\longrightarrow\int_0^\infty u^{'+L(p)+r'}e^{-ju}\,\mathrm du=\frac{\Gamma('+L(p+1)+r')}{j^{'+L(p+1)+r'}}',T('The normalized inner sums are bounded by a constant times the indicated inverse power of j, uniformly in the small parameter. Integral comparison handles small scaled j times t; exponential decay handles large scaled values.'),r'\frac{t^{'+L(p+1)+r'}}j\sum_{k=1}^\infty k^{'+L(p)+r'}e^{-jkt}\le\frac{C}{j^{'+L(p+2)+r'}}',T('The dominating series converges. Pass the limit through the outer sum and restore the logarithm sign.'),r'\lim t^{'+L(p+1)+r'}\ln P(t)=-\Gamma('+L(p+1)+r')\zeta('+L(p+2)+r')'],'arithmetic-lattice-infinite-product-Gamma-zeta-singularity')

@register('limits','maximum-occupancy-threshold','occupancy-extreme-logarithmic-threshold','union-bound-and-conditioned-Poissonization','The maximum occupancy is governed by a threshold where a factorial tail balances the number of boxes. The lower bound needs a dependence argument; conditioning independent Poisson counts closes it with a quantified error.','The coupon collector asks when every box is nonempty. Here the extreme upper occupancy grows logarithmically, and Poissonization is used to prove a lower bound that a union bound cannot supply.',[{'caseId':'normalized-n-balls-n-boxes','purpose':'One normalized probability model; changing an external count scale is not claimed as a fresh advanced case.'}],['binomial tails','Poisson conditioning','Stirling formula','convergence in probability'])
def occupancy(case):
 A=s.Integer(1);counts=[2,1,0,1];total=sum(counts)
 unconditional=s.exp(-len(counts))/s.prod(s.factorial(q) for q in counts);conditionprob=s.exp(-len(counts))*len(counts)**total/s.factorial(total);multinomial=s.factorial(total)/(s.prod(s.factorial(q) for q in counts)*len(counts)**total);ck('Independent finite conditional-Poisson law check',unconditional/conditionprob,multinomial)
 ck('Factorial-moment union-bound combinatorics',s.binomial(7,3)*s.factorial(3),7*6*5)
 analytic('Maximum occupancy logarithmic threshold',['Exactly n independent balls choose uniformly among exactly n boxes. The maximum load is the number of balls in the fullest box.'],['For k=(1+epsilon)ln n/ln ln n, the binomial factorial-moment bound gives P(M_n>=k)<=n/k!; Stirling makes its logarithm at most minus epsilon ln n plus lower-order terms.','For the lower bound use independent Poisson-one counts Y_1,...,Y_n. For k=(1-epsilon)ln n/ln ln n, P(Y_i>=k)>=e^-1/k!=n^(-1+epsilon+o1), so P(max Y_i<k)<=exp(-n^(epsilon+o1)).','Conditioned on sum Y_i=n, the counts have exactly the original multinomial occupancy law. Stirling gives P(sum Y_i=n) asymptotic to1/sqrt(2pi n). Dividing the exponentially small failure probability by this conditioning probability still gives zero.','Combining upper and lower estimates for every fixed positive epsilon proves the stated convergence in probability. Floor and ceiling of the threshold affect only lower-order terms.'])
 return candidate(T('Independently place n balls into n boxes, each ball choosing every box with equal probability. Let ')+r'M_n'+T(' be the largest number of balls in any box. Find the constant c for which, for every positive delta, ')+r'\Pr\!\left(\left|\frac{M_n\ln\ln n}{\ln n}-c\right|<\delta\right)\longrightarrow1\quad(n\to\infty).',A,[(R(1,2),'Lose half the factorial growth when locating the occupancy threshold'),(2,'Double the threshold from a two-sided tail bound'),(0,'Replace the largest load by the bounded average load'),(4,'Apply the two-sided threshold margin twice')],[r'k_+=(1+\varepsilon)\frac{\ln n}{\ln\ln n},\qquad\Pr(M_n\ge\lceil k_+\rceil)\le\frac n{\lceil k_+\rceil!}\longrightarrow0',T('For the lower bound, temporarily make the box counts independent Poisson variables with mean one.'),r'k_-=(1-\varepsilon)\frac{\ln n}{\ln\ln n},\qquad\Pr(Y_i\ge\lfloor k_-\rfloor)\ge\frac{e^{-1}}{\lfloor k_-\rfloor!}=n^{-1+\varepsilon+o(1)}',r'\Pr\!\left(\max_iY_i<\lfloor k_-\rfloor\right)\le\exp(-n^{\varepsilon+o(1)})',T('Conditioning the independent Poisson counts on their sum being n gives exactly the original box counts. The conditioning event has only a polynomially small probability.'),r'\Pr\!\left(\sum_iY_i=n\right)=\frac{e^{-n}n^n}{n!}\sim\frac1{\sqrt{2\pi n}}',T('The lower-tail failure remains negligible after division by this probability. Combining the two bounds and letting the fixed tolerance vary proves the claimed constant.')],'maximum-uniform-occupancy-log-over-loglog-threshold')
